lemma AnalyticAt.prod {e : E} {f : E → F} {g : E → G}
    (hf : AnalyticAt 𝕜 f e) (hg : AnalyticAt 𝕜 g e) :
    AnalyticAt 𝕜 (fun x ↦ (f x, g x)) e

theorem Finset.analyticAt_sum {f : α → E → F} {c : E}
    (N : Finset α) (h : ∀ n ∈ N, AnalyticAt 𝕜 (f n) c) :
    AnalyticAt 𝕜 (∑ n ∈ N, f n) c

theorem analyticAt_matrix_inverse {h : Bulk → Tensor4} {z : Bulk}
    (hh : AnalyticAt ℝ h z) (hn : IsUnit (h z).det) :
    AnalyticAt ℝ (fun y => (h y)⁻¹) z

theorem analyticAt_matrix_of_entries {n : ℕ} {E : Type*}
    [NormedAddCommGroup E] [NormedSpace ℝ E]
    {f : E → Matrix (Fin n) (Fin n) ℝ} {z : E}
    (hf : ∀ a b, AnalyticAt ℝ (fun y => f y a b) z) :
    AnalyticAt ℝ f z

theorem bulkPartial_sum {n : ℕ} {f : Fin n → Bulk → ℝ} {z : Bulk}
    (hf : ∀ a, AnalyticAt ℝ (f a) z) (i : Fin 5) :
    bulkPartial (fun y => ∑ a, f a y) i z = ∑ a, bulkPartial (f a) i z

theorem bulkPartial_metric_germ {g h : Metric} {z : Bulk}
    (he : g =ᶠ[𝓝 z] h) (a b i : Fin 5) :
    bulkPartial (fun y => g y a b) i z = bulkPartial (fun y => h y a b) i z
